/*
min_(u ∈ ℝ^6) uᵀ(∑_i [x_i×n̂_i; n̂_i][(x_i×n̂_i)ᵀ n̂_iᵀ])u - 2uᵀ(∑_i [x_i×n̂_i; n̂_i]n̂_iᵀ(p_i-x_i)) + ∑_i(p_i-x_i)ᵀn̂_i n̂_iᵀ(p_i-x_i)
        where
        x_i: ℝ^3
        n̂_i: ℝ^3
        p_i: ℝ^3  
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include <LBFGS.h>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT ret;
    std::vector<Eigen::Matrix<double, 3, 1>> x;
    std::vector<Eigen::Matrix<double, 3, 1>> n̂;
    std::vector<Eigen::Matrix<double, 3, 1>> p;
    heartlib(
        const std::vector<Eigen::Matrix<double, 3, 1>> & x,
        const std::vector<Eigen::Matrix<double, 3, 1>> & n̂,
        const std::vector<Eigen::Matrix<double, 3, 1>> & p)
    {
        const long dim_0 = x.size();
        assert( n̂.size() == dim_0 );
        assert( p.size() == dim_0 );
        this->x = x;
        this->n̂ = n̂;
        this->p = p;
        auto pack = [&](Eigen::Matrix<DT, 6, 1> & u)
        {
            VectorD vec_joined(6);
            vec_joined << u;
            return vec_joined;
        };
        auto unpack = [&](VectorD & X, Eigen::Matrix<DT, 6, 1> & u)
        {
            u = X(Eigen::seqN(0, 6));
        };
        LBFGSpp::LBFGSParam<DT> param;
        param.epsilon = 1e-6;
        param.max_iterations = 100;
        LBFGSpp::LBFGSSolver<DT> solver(param); 
        auto target = [&](VectorD & X)
        {
            Eigen::Matrix<DT, 6, 1> u;
            unpack(X, u);
            DT sum_0 = 0;
            for(int i=1; i<=x.size(); i++){
                Eigen::Matrix<DT, 6, 1> ret_0;
                ret_0 << (x.at(i-1)).cross(n̂.at(i-1)),
                n̂.at(i-1);
                Eigen::Matrix<DT, 1, 6> ret_1;
                ret_1 << ((x.at(i-1)).cross(n̂.at(i-1))).transpose(), n̂.at(i-1).transpose();
                sum_0 += ret_0 * ret_1;
            }
            DT sum_1 = 0;
            for(int i=1; i<=x.size(); i++){
                Eigen::Matrix<DT, 6, 1> ret_2;
                ret_2 << (x.at(i-1)).cross(n̂.at(i-1)),
                n̂.at(i-1);
                sum_1 += ret_2 * n̂.at(i-1).transpose() * (p.at(i-1) - x.at(i-1));
            }
            DT sum_2 = 0;
            for(int i=1; i<=p.size(); i++){
                sum_2 += (DT)((DT)((p.at(i-1) - x.at(i-1)).transpose() * n̂.at(i-1)) * n̂.at(i-1).transpose() * (p.at(i-1) - x.at(i-1)));
            }
            return (DT)(u.transpose() * (sum_0) * u) - (DT)(DT(2) * u.transpose() * (sum_1)) + sum_2;
        };
        double eps = 1e-6;
        auto helper = [&](VectorD & X, VectorD & grad)
        {
            double f_X = target(X);
            for(int i = 0; i < grad.size(); ++i )
            {
                const double X_i = X[i];
                X[i] += eps;
                grad[i] = (target(X) - f_X)/eps;
                X[i] = X_i;
            }
            return f_X;
        };
        VectorD init = VectorD::Zero(6);
        double fx;
        ret = solver.minimize(helper, init, fx);
    }
};

