function output = heartlib(x, n_hat, p)
% output = heartlib(x, n̂, p)
%
%    min_(u ∈ ℝ^6) uᵀ(∑_i [x_i×n̂_i; n̂_i][(x_i×n̂_i)ᵀ n̂_iᵀ])u - 2uᵀ(∑_i [x_i×n̂_i; n̂_i]n̂_iᵀ(p_i-x_i)) + ∑_i(p_i-x_i)ᵀn̂_i n̂_iᵀ(p_i-x_i)
%            where
%            x_i: ℝ^3
%            n̂_i: ℝ^3
%            p_i: ℝ^3  
    dim_0 = size(x, 1);
    assert( isequal(size(x), [dim_0, 3]) );
    assert( isequal(size(n_hat), [dim_0, 3]) );
    assert( isequal(size(p), [dim_0, 3]) );

    u = optimvar('u', 6);
    function ret = target(u)
        sum_0 = 0;
        for i = 1:size(x, 1)
            ret_0 = [[reshape(cross(x(i,:)', n_hat(i,:)'), [3, 1])]; [reshape(n_hat(i,:)', [3, 1])]];
            ret_1 = [[(cross(x(i,:)', n_hat(i,:)'))', n_hat(i,:)'']];
            sum_0 = sum_0 + ret_0 * ret_1;
        end
        sum_1 = 0;
        for i = 1:size(x, 1)
            ret_2 = [[reshape(cross(x(i,:)', n_hat(i,:)'), [3, 1])]; [reshape(n_hat(i,:)', [3, 1])]];
            sum_1 = sum_1 + ret_2 * n_hat(i,:)'' * (p(i,:)' - x(i,:)');
        end
        sum_2 = 0;
        for i = 1:size(p, 1)
            sum_2 = sum_2 + (p(i,:)' - x(i,:)')' * n_hat(i,:)' * n_hat(i,:)'' * (p(i,:)' - x(i,:)');
        end
        ret = u' * (sum_0) * u - 2 * u' * (sum_1) + sum_2;
    end
    [~, optimize] = fminunc(@target,zeros(6,1));
    ret = optimize;
    output.ret = ret;
    output.x = x;    
    output.n_hat = n_hat;    
    output.p = p;
end

